#include <bits/stdc++.h>
using namespace std;

#define MAXN (1 << 19 | 5)
#define MAXP 20

int n, k, p;
int lim, cnt[MAXN], poly[MAXN];
int layer1[MAXP][MAXN], layer2[MAXP][MAXN], layer3[MAXP][MAXN];
long long modSq;
long long inter[MAXP][MAXN];
long long fact[MAXN], invf[MAXN];

long long powmod(long long a, long long b) {
    long long r = 1;
    while (b) {
        if (b & 1) r = r * a % p;
        a = a * a % p;
        b >>= 1;
    }
    return r;
}

void init_fact() {
    fact[0] = 1;
    for (int i = 1; i <= lim; i++) fact[i] = fact[i - 1] * i % p;
    invf[lim] = powmod(fact[lim], p - 2);
    for (int i = lim - 1; i >= 0; i--) invf[i] = invf[i + 1] * (i + 1) % p;
}

int pow2_minus1(int x) {
    int s = 1;
    while (s < x) s <<= 1;
    return s - 1;
}

void hadamard(int *arr, int len, bool rev = false) {
    long long *tmp = inter[0];
    for (int i = 0; i < len; i++) tmp[i] = arr[i];
    if (rev) {
        for (int h = 1; h < len; h <<= 1)
            for (int i = 0; i < len; i += (h << 1))
                for (int j = i; j < i + h; j++)
                    tmp[j + h] -= tmp[j];
    } else {
        for (int h = 1; h < len; h <<= 1)
            for (int i = 0; i < len; i += (h << 1))
                for (int j = i; j < i + h; j++)
                    tmp[j + h] += tmp[j];
    }
    for (int i = 0; i < len; i++) {
        arr[i] = tmp[i] % p;
        if (arr[i] < 0) arr[i] += p;
    }
}

static inline void add_mod(long long &x) {
    if (x >= modSq) x -= modSq;
}

void multiply_poly() {
    for (int i = 0; i < MAXP; i++) {
        memset(layer1[i], 0, sizeof(int) * (lim + 1));
        memset(inter[i], 0, sizeof(long long) * (lim + 1));
    }
    for (int i = 0; i <= lim; i++) layer1[cnt[i]][i] = poly[i];
    for (int i = 0; i < MAXP; i++) hadamard(layer1[i], lim + 1);
    for (int a = 0; a < MAXP; a++)
        for (int b = 0; a + b < MAXP; b++)
            for (int i = 0; i <= lim; i++)
                add_mod(inter[a + b][i] += 1LL * layer1[a][i] * layer2[b][i]);
    for (int a = 0; a < MAXP; a++)
        for (int i = 0; i <= lim; i++)
            layer3[a][i] = inter[a][i] % p;
    for (int a = 0; a < MAXP; a++) hadamard(layer3[a], lim + 1, true);
    for (int i = 0; i <= lim; i++) poly[i] = layer3[cnt[i]][i];
}

void multiply_self() {
    static int tmp[MAXP][MAXN];
    for (int i = 0; i < MAXP; i++) memset(inter[i], 0, sizeof(long long) * (lim + 1));
    for (int a = 0; a < MAXP; a++)
        for (int b = 0; a + b < MAXP; b++)
            for (int i = 0; i <= lim; i++)
                add_mod(inter[a + b][i] += 1LL * layer2[a][i] * layer2[b][i]);
    for (int a = 0; a < MAXP; a++)
        for (int i = 0; i <= lim; i++)
            tmp[a][i] = inter[a][i] % p;
    for (int a = 0; a < MAXP; a++) hadamard(tmp[a], lim + 1, true);
    for (int a = 0; a < MAXP; a++) memset(layer2[a], 0, sizeof(int) * (lim + 1));
    for (int i = 0; i <= lim; i++) layer2[cnt[i]][i] = tmp[cnt[i]][i];
    for (int a = 0; a < MAXP; a++) hadamard(layer2[a], lim + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &p);
    modSq = 1LL * p * p;
    if (n & 1) {
        printf("%lld", powmod(k, n));
        return 0;
    }
    poly[0] = 1;
    lim = pow2_minus1(n + 1);
    init_fact();
    for (int i = 0; i <= lim; i++) cnt[i] = __builtin_popcount(i);
    for (int i = 0; i <= lim; i++) layer2[cnt[i]][i] = invf[i];
    for (int i = 0; i < MAXP; i++) hadamard(layer2[i], lim + 1);
    int orig_k = k;
    while (k) {
        cerr << k << endl;
        if (k & 1) multiply_poly();
        k >>= 1;
        if (k) multiply_self();
    }
    printf("%lld", (powmod(orig_k, n) - fact[n] * poly[n] % p + p) % p);
    return 0;
}
